using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SchoolERP.Domain.Entities;
namespace SchoolERP.Infrastructure.Persistence.Configurations;
public sealed class DepartmentConfiguration:IEntityTypeConfiguration<Department>{public void Configure(EntityTypeBuilder<Department>b){b.ToTable("departments",t=>{t.HasCheckConstraint("ck_departments_order","display_order >= 0");t.HasCheckConstraint("ck_departments_status","status BETWEEN 1 AND 4");});b.ConfigureAudit();b.Property(x=>x.TenantId).HasColumnName("tenant_id");b.Property(x=>x.SchoolId).HasColumnName("school_id");b.Property(x=>x.CampusId).HasColumnName("campus_id");b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(150).IsRequired();b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50).IsRequired();b.Property(x=>x.ShortName).HasColumnName("short_name").HasMaxLength(50);b.Property(x=>x.Type).HasColumnName("type").HasConversion<int>();b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.Property(x=>x.HeadName).HasColumnName("head_name").HasMaxLength(200);b.Property(x=>x.Email).HasColumnName("email").HasMaxLength(320);b.Property(x=>x.Phone).HasColumnName("phone").HasMaxLength(30);b.Property(x=>x.Location).HasColumnName("location").HasMaxLength(200);b.Property(x=>x.Status).HasColumnName("status").HasConversion<int>();b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(1000);b.Property(x=>x.ActivatedAt).HasColumnName("activated_at");b.Property(x=>x.DeactivatedAt).HasColumnName("deactivated_at");b.Property(x=>x.ArchivedAt).HasColumnName("archived_at");b.HasOne(x=>x.Tenant).WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.School).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Campus).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.CampusId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.TenantId);b.HasIndex(x=>x.SchoolId);b.HasIndex(x=>x.CampusId);b.HasIndex(x=>new{x.SchoolId,x.Code}).IsUnique().HasDatabaseName("ux_departments_school_code");b.HasIndex(x=>new{x.SchoolId,x.Status});b.HasIndex(x=>new{x.SchoolId,x.Type});b.HasIndex(x=>new{x.SchoolId,x.CampusId});b.HasIndex(x=>new{x.SchoolId,x.DisplayOrder});}}
